export declare const PGSCOPE_CSS = "\n:host {\n  display: block;\n}\n.pgs-root {\n  --pgs-bg: #0c0f14;\n  --pgs-surface: #131720;\n  --pgs-surface-2: #1b2130;\n  --pgs-ink: #f3f4f6;\n  --pgs-ink-soft: #cbd5e1;\n  --pgs-ink-faint: #8b95a7;\n  --pgs-line: #232a38;\n  --pgs-line-strong: #343d50;\n  --pgs-accent: #ff7a33;\n  --pgs-blue: #60a5fa;\n  --pgs-ok: #34d399;\n  --pgs-warn: #fbbf24;\n  --pgs-danger: #f87171;\n  --pgs-heat-1: rgba(251, 191, 36, 0.10);\n  --pgs-heat-2: rgba(255, 122, 51, 0.16);\n  --pgs-heat-3: rgba(248, 113, 113, 0.22);\n  --pgs-sans: -apple-system, BlinkMacSystemFont, \"Inter\", \"Segoe UI\", Roboto, sans-serif;\n  --pgs-mono: ui-monospace, \"SFMono-Regular\", Menlo, Monaco, Consolas, monospace;\n  font-family: var(--pgs-sans);\n  font-size: 13px;\n  line-height: 1.45;\n  color: var(--pgs-ink);\n  background: var(--pgs-bg);\n  border: 1px solid var(--pgs-line);\n  border-radius: 4px;\n  overflow: hidden;\n  -webkit-font-smoothing: antialiased;\n}\n.pgs-root[data-theme=\"light\"] {\n  --pgs-bg: #ffffff;\n  --pgs-surface: #fafafa;\n  --pgs-surface-2: #f4f4f5;\n  --pgs-ink: #111827;\n  --pgs-ink-soft: #374151;\n  --pgs-ink-faint: #6b7280;\n  --pgs-line: #e5e7eb;\n  --pgs-line-strong: #d1d5db;\n  --pgs-accent: #ea580c;\n  --pgs-blue: #1d4ed8;\n  --pgs-ok: #047857;\n  --pgs-warn: #b45309;\n  --pgs-danger: #b91c1c;\n  --pgs-heat-1: rgba(180, 83, 9, 0.08);\n  --pgs-heat-2: rgba(234, 88, 12, 0.12);\n  --pgs-heat-3: rgba(185, 28, 28, 0.16);\n}\n.pgs-root *, .pgs-root *::before, .pgs-root *::after {\n  box-sizing: border-box;\n}\n.pgs-mono {\n  font-family: var(--pgs-mono);\n  font-variant-numeric: tabular-nums;\n}\n.pgs-summary {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px 16px;\n  padding: 10px 14px;\n  background: var(--pgs-surface);\n  border-bottom: 1px solid var(--pgs-line);\n}\n.pgs-stats {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  gap: 8px 20px;\n}\n.pgs-stat {\n  display: flex;\n  flex-direction: column;\n  gap: 1px;\n}\n.pgs-stat-lbl {\n  font-size: 11px;\n  color: var(--pgs-ink-faint);\n  font-weight: 500;\n}\n.pgs-stat-val {\n  font-family: var(--pgs-mono);\n  font-variant-numeric: tabular-nums;\n  font-size: 14px;\n  font-weight: 600;\n  color: var(--pgs-ink);\n}\n.pgs-stat-sub {\n  font-size: 11px;\n  color: var(--pgs-ink-faint);\n  font-weight: 400;\n  margin-left: 4px;\n}\n.pgs-summary-right {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  flex-wrap: wrap;\n}\n.pgs-meta-strip {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px 14px;\n  padding: 6px 14px;\n  border-bottom: 1px solid var(--pgs-line);\n  font-size: 11.5px;\n  color: var(--pgs-ink-soft);\n  background: var(--pgs-bg);\n}\n.pgs-meta-item code {\n  font-family: var(--pgs-mono);\n  font-size: 11px;\n  background: var(--pgs-surface-2);\n  padding: 1px 4px;\n  border-radius: 3px;\n  color: var(--pgs-ink);\n}\n.pgs-diag {\n  border-bottom: 1px solid var(--pgs-line);\n  background: var(--pgs-bg);\n}\n.pgs-diag-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  padding: 7px 14px;\n  cursor: pointer;\n  user-select: none;\n  font-size: 12px;\n  color: var(--pgs-ink-soft);\n}\n.pgs-diag-head:hover {\n  background: var(--pgs-surface);\n}\n.pgs-diag-summary {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n  font-weight: 500;\n  min-width: 0;\n}\n.pgs-diag-preview {\n  color: var(--pgs-ink-faint);\n  font-weight: 400;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  max-width: 480px;\n}\n.pgs-diag-row .pgs-btn {\n  max-width: 240px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  flex-shrink: 0;\n}\n.pgs-diag-list {\n  display: flex;\n  flex-direction: column;\n  border-top: 1px solid var(--pgs-line);\n}\n.pgs-diag-row {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 10px;\n  padding: 7px 14px;\n  border-bottom: 1px solid var(--pgs-line);\n  font-size: 12px;\n}\n.pgs-diag-row:last-child {\n  border-bottom: 0;\n}\n.pgs-diag-row:hover {\n  background: var(--pgs-surface);\n}\n.pgs-diag-main {\n  display: flex;\n  align-items: baseline;\n  gap: 8px;\n  min-width: 0;\n  flex: 1;\n}\n.pgs-diag-txt {\n  min-width: 0;\n}\n.pgs-diag-title {\n  font-weight: 600;\n  color: var(--pgs-ink);\n}\n.pgs-diag-detail {\n  color: var(--pgs-ink-faint);\n  margin-left: 6px;\n}\n.pgs-sev {\n  display: inline-block;\n  font-size: 10.5px;\n  font-weight: 600;\n  padding: 1px 6px;\n  border-radius: 3px;\n  border: 1px solid var(--pgs-line-strong);\n  white-space: nowrap;\n  flex-shrink: 0;\n}\n.pgs-sev-high {\n  color: var(--pgs-danger);\n  border-color: var(--pgs-danger);\n}\n.pgs-sev-med {\n  color: var(--pgs-warn);\n  border-color: var(--pgs-warn);\n}\n.pgs-sev-low {\n  color: var(--pgs-blue);\n  border-color: var(--pgs-blue);\n}\n.pgs-btn {\n  appearance: none;\n  background: transparent;\n  border: 1px solid var(--pgs-line-strong);\n  color: var(--pgs-ink-soft);\n  font-family: var(--pgs-sans);\n  font-size: 12px;\n  font-weight: 500;\n  padding: 4px 9px;\n  border-radius: 3px;\n  cursor: pointer;\n  line-height: 1.25;\n  white-space: nowrap;\n}\n.pgs-btn:hover {\n  color: var(--pgs-ink);\n  border-color: var(--pgs-ink-soft);\n}\n.pgs-btn.active {\n  background: var(--pgs-ink);\n  color: var(--pgs-bg);\n  border-color: var(--pgs-ink);\n}\n.pgs-btn-sm {\n  font-size: 11px;\n  padding: 2px 7px;\n}\n.pgs-toolbar {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  padding: 8px 14px;\n  background: var(--pgs-bg);\n  border-bottom: 1px solid var(--pgs-line);\n}\n.pgs-btn-group {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  flex-wrap: wrap;\n}\n.pgs-select, .pgs-input {\n  background: var(--pgs-surface);\n  border: 1px solid var(--pgs-line-strong);\n  color: var(--pgs-ink);\n  font-family: var(--pgs-sans);\n  font-size: 12px;\n  padding: 4px 8px;\n  border-radius: 3px;\n  outline: none;\n}\n.pgs-input {\n  min-width: 150px;\n}\n.pgs-input:focus, .pgs-select:focus {\n  border-color: var(--pgs-accent);\n}\n.pgs-workspace {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr);\n}\n.pgs-workspace.with-insp {\n  grid-template-columns: minmax(0, 1fr) 310px;\n}\n.pgs-workspace.with-insp .pgs-node-sub {\n  display: none;\n}\n.pgs-workspace.with-insp .pgs-table .pgs-node-title {\n  max-width: 210px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n@media (max-width: 860px) {\n  .pgs-workspace.with-insp {\n    grid-template-columns: minmax(0, 1fr);\n  }\n  .pgs-inspector {\n    border-left: 0 !important;\n    border-top: 1px solid var(--pgs-line);\n  }\n}\n.pgs-main {\n  min-width: 0;\n  overflow: auto;\n}\n/* Compact Table View */\n.pgs-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 12px;\n}\n.pgs-table th, .pgs-table td {\n  padding: 5px 7px;\n  border-bottom: 1px solid var(--pgs-line);\n  text-align: left;\n  vertical-align: middle;\n}\n.pgs-table th {\n  position: sticky;\n  top: 0;\n  z-index: 2;\n  background: var(--pgs-surface);\n  color: var(--pgs-ink-faint);\n  font-size: 11px;\n  font-weight: 600;\n  white-space: nowrap;\n}\n.pgs-table th.num, .pgs-table td.num {\n  text-align: right;\n  font-family: var(--pgs-mono);\n  font-variant-numeric: tabular-nums;\n  white-space: nowrap;\n}\n.pgs-table tbody tr {\n  cursor: pointer;\n}\n.pgs-table tbody tr:hover td {\n  background: var(--pgs-surface);\n}\n.pgs-table tbody tr.selected td {\n  background: var(--pgs-surface-2);\n}\n.pgs-table tbody tr.dimmed {\n  opacity: 0.42;\n}\n.pgs-node-cell {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n  min-width: 170px;\n}\n.pgs-fold-btn {\n  appearance: none;\n  background: transparent;\n  border: 0;\n  color: var(--pgs-ink-faint);\n  width: 16px;\n  height: 16px;\n  padding: 0;\n  cursor: pointer;\n  font-size: 10px;\n  flex-shrink: 0;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n}\n.pgs-fold-btn:hover {\n  color: var(--pgs-ink);\n}\n.pgs-fold-spacer {\n  width: 16px;\n  flex-shrink: 0;\n}\n.pgs-node-title {\n  font-weight: 600;\n  color: var(--pgs-ink);\n}\n.pgs-node-sub {\n  color: var(--pgs-ink-faint);\n  font-size: 11px;\n  margin-left: 6px;\n  font-family: var(--pgs-mono);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  max-width: 300px;\n}\n.pgs-pill {\n  display: inline-block;\n  font-size: 10.5px;\n  font-weight: 500;\n  padding: 0px 5px;\n  border-radius: 3px;\n  border: 1px solid var(--pgs-line-strong);\n  color: var(--pgs-ink-soft);\n  background: var(--pgs-surface);\n  white-space: nowrap;\n}\n.pgs-pill-warn {\n  color: var(--pgs-warn);\n  border-color: var(--pgs-warn);\n}\n.pgs-pill-danger {\n  color: var(--pgs-danger);\n  border-color: var(--pgs-danger);\n}\n.pgs-pill-ok {\n  color: var(--pgs-ok);\n  border-color: var(--pgs-ok);\n}\n.pgs-pill-blue {\n  color: var(--pgs-blue);\n  border-color: var(--pgs-blue);\n}\n.pgs-bar-wrap {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-end;\n  gap: 2px;\n}\n.pgs-bar-track {\n  width: 68px;\n  height: 4px;\n  background: var(--pgs-surface-2);\n  border-radius: 2px;\n  overflow: hidden;\n}\n.pgs-bar-fill {\n  height: 100%;\n  background: var(--pgs-accent);\n}\n.pgs-bar-fill.blue {\n  background: var(--pgs-blue);\n}\n.pgs-heat-1 { background: var(--pgs-heat-1) !important; }\n.pgs-heat-2 { background: var(--pgs-heat-2) !important; }\n.pgs-heat-3 { background: var(--pgs-heat-3) !important; }\n/* Interactive Tree View */\n.pgs-tree-wrap {\n  padding: 14px;\n  overflow: auto;\n}\n.pgs-tree-node {\n  position: relative;\n}\n.pgs-tree-children {\n  margin-left: 20px;\n  padding-left: 14px;\n  border-left: 1px solid var(--pgs-line-strong);\n}\n.pgs-tree-card {\n  position: relative;\n  border: 1px solid var(--pgs-line);\n  border-radius: 4px;\n  background: var(--pgs-surface);\n  padding: 8px 10px;\n  margin-bottom: 8px;\n  cursor: pointer;\n}\n.pgs-tree-children > .pgs-tree-node > .pgs-tree-card::before {\n  content: \"\";\n  position: absolute;\n  left: -15px;\n  top: 16px;\n  width: 14px;\n  height: 1px;\n  background: var(--pgs-line-strong);\n}\n.pgs-tree-card:hover {\n  border-color: var(--pgs-line-strong);\n}\n.pgs-tree-card.selected {\n  border-color: var(--pgs-accent);\n  background: var(--pgs-surface-2);\n}\n.pgs-tree-card.dimmed {\n  opacity: 0.42;\n}\n.pgs-tree-top {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n.pgs-tree-left {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  min-width: 0;\n  flex-wrap: wrap;\n}\n.pgs-tree-metrics {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  font-family: var(--pgs-mono);\n  font-variant-numeric: tabular-nums;\n  font-size: 11.5px;\n  color: var(--pgs-ink-soft);\n}\n.pgs-tree-qual {\n  margin-top: 4px;\n  font-family: var(--pgs-mono);\n  font-size: 11px;\n  color: var(--pgs-ink-faint);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.pgs-tree-bar {\n  margin-top: 6px;\n  height: 4px;\n  background: var(--pgs-bg);\n  border-radius: 2px;\n  overflow: hidden;\n  display: flex;\n}\n.pgs-tree-bar-self {\n  height: 100%;\n  background: var(--pgs-accent);\n}\n.pgs-tree-bar-child {\n  height: 100%;\n  background: var(--pgs-line-strong);\n}\n/* Flame / Waterfall View */\n.pgs-flame-wrap {\n  padding: 10px 14px;\n}\n.pgs-flame-axis {\n  display: grid;\n  grid-template-columns: minmax(150px, 34%) minmax(120px, 1fr) minmax(96px, auto);\n  gap: 10px;\n  align-items: center;\n  padding-bottom: 6px;\n  margin-bottom: 4px;\n  border-bottom: 1px solid var(--pgs-line);\n  font-size: 11px;\n  color: var(--pgs-ink-faint);\n}\n.pgs-flame-ticks {\n  display: flex;\n  justify-content: space-between;\n  font-family: var(--pgs-mono);\n  font-variant-numeric: tabular-nums;\n}\n.pgs-flame-row {\n  display: grid;\n  grid-template-columns: minmax(150px, 34%) minmax(120px, 1fr) minmax(96px, auto);\n  gap: 10px;\n  align-items: center;\n  padding: 5px 4px;\n  border-bottom: 1px solid var(--pgs-line);\n  cursor: pointer;\n  font-size: 12px;\n}\n.pgs-flame-row:hover {\n  background: var(--pgs-surface);\n}\n.pgs-flame-row.selected {\n  background: var(--pgs-surface-2);\n}\n.pgs-flame-row.dimmed {\n  opacity: 0.42;\n}\n.pgs-flame-lbl {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n}\n.pgs-flame-track {\n  position: relative;\n  height: 16px;\n  background: var(--pgs-surface);\n  border: 1px solid var(--pgs-line);\n  border-radius: 2px;\n  overflow: hidden;\n}\n.pgs-flame-incl {\n  position: absolute;\n  top: 2px;\n  bottom: 2px;\n  background: var(--pgs-line-strong);\n  border-radius: 1px;\n}\n.pgs-flame-excl {\n  position: absolute;\n  top: 2px;\n  bottom: 2px;\n  background: var(--pgs-accent);\n  border-radius: 1px;\n}\n.pgs-flame-val {\n  text-align: right;\n  font-family: var(--pgs-mono);\n  font-variant-numeric: tabular-nums;\n  font-size: 11.5px;\n  white-space: nowrap;\n}\n/* Text / JSON View */\n.pgs-code-wrap {\n  padding: 12px 14px;\n}\n.pgs-code-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  margin-bottom: 8px;\n  font-size: 11.5px;\n  color: var(--pgs-ink-faint);\n}\n.pgs-pre {\n  margin: 0;\n  padding: 10px 12px;\n  background: var(--pgs-surface);\n  border: 1px solid var(--pgs-line);\n  border-radius: 4px;\n  font-family: var(--pgs-mono);\n  font-size: 12px;\n  line-height: 1.5;\n  overflow-x: auto;\n  color: var(--pgs-ink);\n  white-space: pre;\n}\n.pgs-tok-node { color: var(--pgs-ink); font-weight: 600; }\n.pgs-tok-cost { color: var(--pgs-ink-faint); }\n.pgs-tok-act { color: var(--pgs-accent); }\n.pgs-tok-buf { color: var(--pgs-blue); }\n.pgs-tok-warn { color: var(--pgs-warn); }\n/* Inspector Panel */\n.pgs-inspector {\n  border-left: 1px solid var(--pgs-line);\n  background: var(--pgs-surface);\n  padding: 12px 14px;\n  overflow-y: auto;\n  font-size: 12px;\n}\n.pgs-insp-head {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 8px;\n  padding-bottom: 8px;\n  border-bottom: 1px solid var(--pgs-line);\n  margin-bottom: 10px;\n}\n.pgs-insp-title {\n  font-size: 13px;\n  font-weight: 700;\n  color: var(--pgs-ink);\n  overflow-wrap: anywhere;\n  word-break: normal;\n}\n.pgs-insp-sub {\n  font-size: 11px;\n  color: var(--pgs-ink-faint);\n  margin-top: 2px;\n}\n.pgs-insp-sec {\n  margin-bottom: 12px;\n  padding-bottom: 10px;\n  border-bottom: 1px solid var(--pgs-line);\n}\n.pgs-insp-sec:last-child {\n  border-bottom: 0;\n  margin-bottom: 0;\n  padding-bottom: 0;\n}\n.pgs-insp-sec-title {\n  font-size: 11px;\n  font-weight: 600;\n  color: var(--pgs-ink-faint);\n  margin-bottom: 6px;\n}\n.pgs-kv {\n  display: grid;\n  grid-template-columns: auto minmax(0, 1fr);\n  gap: 4px 10px;\n  align-items: baseline;\n}\n.pgs-k {\n  color: var(--pgs-ink-faint);\n  white-space: nowrap;\n}\n.pgs-v {\n  text-align: right;\n  font-family: var(--pgs-mono);\n  font-variant-numeric: tabular-nums;\n  color: var(--pgs-ink);\n  word-break: break-word;\n}\n.pgs-expr {\n  font-family: var(--pgs-mono);\n  font-size: 11px;\n  background: var(--pgs-bg);\n  border: 1px solid var(--pgs-line);\n  border-radius: 3px;\n  padding: 5px 7px;\n  margin-top: 4px;\n  white-space: pre-wrap;\n  word-break: break-word;\n  color: var(--pgs-ink-soft);\n}\n.pgs-worker-tbl {\n  width: 100%;\n  border-collapse: collapse;\n  font-family: var(--pgs-mono);\n  font-size: 11px;\n  margin-top: 4px;\n}\n.pgs-worker-tbl th, .pgs-worker-tbl td {\n  padding: 3px 5px;\n  border-bottom: 1px solid var(--pgs-line);\n  text-align: right;\n}\n.pgs-worker-tbl th:first-child, .pgs-worker-tbl td:first-child {\n  text-align: left;\n}\n@media (max-width: 600px) {\n  .pgs-diag-preview { display: none; }\n  .pgs-flame-axis, .pgs-flame-row {\n    grid-template-columns: minmax(110px, 42%) minmax(70px, 1fr) auto;\n    gap: 6px;\n  }\n}\n.pgs-error {\n  padding: 14px;\n  color: var(--pgs-danger);\n  font-family: var(--pgs-mono);\n  font-size: 12px;\n}\n";
